local TowerRankCellNode = Class('TowerRankCellNode')

function TowerRankCellNode:__init()
    self.cb = nil
    self.data = nil
    self.position = nil
end

function TowerRankCellNode:__delete()
    self.cb = nil
    self.data = nil
    self.position = nil
end

function TowerRankCellNode:Awake()
    CfUtils.SetActive(self.BtnNode, true)
    SetButtonAction(self.BtnNode, function()
        if self.cb then
            self.cb(Constants.TowerType.Main, self.data)
        end
    end)
end

function TowerRankCellNode:FreshUI(playerInfo, position, cb)
    self.cb = cb
    self.data = playerInfo
    self.position = position
    CfUtils.FillText(self.TextRank, string.format('No.%d', position))
    CfUtils.FillText(self.TextName, playerInfo.name)
    CfUtils.FillText(self.TextNumber3, playerInfo.score)
    CfUtils.FillText(self.TextNumberFloor, playerInfo.score)
    CfUtils.SetUISwitchText(self.TextRank, math.max(1,math.min(2, position)))
    ---@type CommonPlayerHeadNode
    local env = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, PlayerHeadNodePath)
    if not isNull(env) then
        env:SetCallBack(function()
            ---头像的点击跳转事件
            if cb then
                cb()
            end
        end)
    end
    env:FreshAvatarFrame(playerInfo.avatar, playerInfo.avatarFrame)
end

function TowerRankCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

